#include <algorithm>
#include <iostream>
#include <iterator>

int main() {
    int arr[] = { 3, 1, 4, 1, 5 };

    // Using std::begin/std::end (noninvasive approach)
    // The array definition itself is not modified.
    std::sort(std::begin(arr), std::end(arr));

    for (int x : arr) {
        std::cout << x << " "; // Output: 1 1 3 4 5
    }
}
